head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
eval함수는 자동변환에 제약이 많습니다. ASIS소스 확인 후 변환해주세요.
eval함수 사용 수: 2

 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDSTF39302.xml";
scwin.contnId;
scwin.sIsurCd;
scwin.sSeq;
scwin.sComNm;
scwin.checkYYYY;
scwin.jobType;
scwin.ToDay = new Date();
scwin.gSTRT_YYYY = parseInt(scwin.ToDay.getYear(), 10) - 1;
scwin.gEND_YYYY = parseInt(scwin.ToDay.getYear(), 10) + 8;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetHeader = function() {
    dts_Detail.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECL_COM_ADM_INOUT";
    dts_Detail.Reset();
    dts_Detail.insertRow();
    dts_List.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=SPECL_APPL_YY_INOUT";
    dts_List.Reset();
};


//적용년도 목록 List 2018년도 ~ 현재년도 +6
scwin.fn_setCode = function() {
    var str = "";
    for (var i = 2018; i <= scwin.gEND_YYYY; i++) {
        str += i + ":" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    $c.cm.setColumnProp(grd_Grid, 'SPECL_APPL_YY', 'Data', str);


    //  지식구분 셋팅
    dts_speclApplTpCd.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=&CD_ENG_NM=SPECL_APPL_TP_CD";
    dts_speclApplTpCd.Reset();
};



//상세데이터 불러오기
scwin.fn_read = function(isurcd, comseq) {
    trs_Read.Action = "/ExceptionRuleAdm.do?method=readExceptionRuleAdm" + "&ISUR_CD=" + isurcd + "&SPECL_COM_SEQ=" + comseq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_Detail,O:pOutput3=dts_fileList)";
    trs_Read.Post();


    /* useupdate를 false로 지정함. */
    var url = "/ExceptionRuleAdm.do?method=listExceptionRuleYear" + "&ISUR_CD=" + isurcd + "&SPECL_COM_SEQ=" + comseq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};



//적용년도 중복입력 체크
scwin.fn_checkYYYY = function() {
    var url = "/ExceptionRuleAdm.do?method=listExcpRuleIsurCnt" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&SPECL_COM_SEQ=" + $c.stf.getObjectValue(txb_seq) + "&FLAG_TYPE=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_yyyyCnt.DataID = encodeURI(url);
    dts_yyyyCnt.reset();
};



//저장 시 체크사항
scwin.fn_check = function() {
    //이전에 입력된 회사데이터 가져오기
    scwin.fn_checkYYYY();
    if (txb_com_abbrv.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "회사명"));
        txb_isur_cd.focus();
        return false;
    }
    if (edt_SubmitDate.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "신청서제출일"));
        edt_SubmitDate.focus();
        return false;
    }
    if (edt_speclDate.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "특례적용일"));
        edt_speclDate.focus();
        return false;
    }
    if (dts_List.getTotalRow() <= 0) {
        $c.win.alert("적용년도를 1개 이상 입력해 주십시요");
        return false;
    }

    //grd_Grid.redraw = true;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "SPECL_APPL_YY") == "" || dts_List.getCellData(i, "SPECL_APPL_TP_CD") == "") {
            $c.win.alert("입력하지 않은 적용년도와 적용구분이 있습니다. 확인해 주십시요. ");
            return false;
        }
    }
    var T;
    for (var k = 1; k <= dts_List.getTotalRow(); k++) {
        T = 0;
        for (var s = 1; s <= dts_List.getTotalRow(); s++) {
            if (dts_List.getCellData(k, "SPECL_APPL_YY") == dts_List.getCellData(s, "SPECL_APPL_YY")) {
                T++;
                if (T > 1) {
                    $c.win.alert("동일한 년도가 입력되어 있습니다. 확인해 주십시요");
                    return false;
                }
            }
        }
    }
    var yyyyStr;
    var cnt = 0;
    if (dts_yyyyCnt.getTotalRow() > 0) {
        for (var k = 1; k <= dts_yyyyCnt.getTotalRow(); k++) {
            T = 0;
            for (var s = 1; s <= dts_List.getTotalRow(); s++) {
                if (dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY") == dts_List.getCellData(s, "SPECL_APPL_YY")) {
                    T++;
                    if (T > 0) {
                        cnt++;
                        if (cnt <= 1) {
                            yyyyStr = dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY");
                        } else {
                            yyyyStr += "," + dts_yyyyCnt.getCellData(k, "SPECL_APPL_YY");
                        }
                    }
                }
            }
        }
        if (cnt > 0) {
            $c.win.alert("해당회사로  " + yyyyStr + " 년도가 이미 입력되어 있습니다. 확인해 주십시요");
            return false;
        }
    }
    if (txb_skilValuGrd.getValue() != "") {
        if (!scwin.checkMaxLength1(txb_skilValuGrd, 100, "기술성평가등급")) {
            txb_skilValuGrd.focus();
            return false;
        }
    }
    if (txb_valuInstNm.getValue() != "" && !scwin.checkMaxLength1(txb_valuInstNm, 100, "전문평가기관명")) {
        txb_valuInstNm.focus();
        return false;
    }
    if (tarea_contn.getValue() != "" && !scwin.checkMaxLength2(tarea_contn, 2000, "비고")) {
        tarea_contn.focus();
        return false;
    }
    return true;
};

//저장
scwin.fn_save = function() {
    if (scwin.fn_check() == false) {
        return false;
    }
    scwin.jobType = "저장";
    var methodStr = "";
    if (scwin.contnId == "I") {
        methodStr = "registerExceptionRuleAdm";
    } else {
        methodStr = "modifyExceptionRuleAdm";
    }
    var rtn = confirm(scwin.jobType + ' 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_Detail.setCellData(1, "FLAG_TYPE", scwin.contnId);
        dts_Detail.setCellData(1, "LST_CHG_EMP_NO", js_emp_no);
        trs_Save.Action = "/ExceptionRuleAdm.do?method=" + methodStr + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pDetail=dts_Detail,I:pInput=dts_List,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};




//삭제
scwin.fn_delete = function() {
    scwin.jobType = "삭제";
    var rtn = confirm(scwin.jobType + ' 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_Detail.setCellData(1, "FLAG_TYPE", scwin.contnId);
        dts_Detail.setCellData(1, "LST_CHG_EMP_NO", js_emp_no);
        trs_Delete.Action = "/ExceptionRuleAdm.do?method=deleteExceptionRuleAdm&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Delete.KeyValue = "JSP(I:pDetail=dts_Detail)";
        trs_Delete.Post();
    }
};




//파일 헤더 생성
scwin.fn_setFileDataHeader = function() {

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};


//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    //alert(txb_seq.value);
    location.href = "/filedownload.do?SPECL_COM_SEQ=" + scwin.sSeq + "&ATTACH_SEQ=" + attach_seq + "&gubun=36";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};


//신청서제출일 입력시 적용년도가 자동으로 셋팅 된다.
scwin.fn_autoYYYY = function() {
    var gSubmitDate = edt_SubmitDate.getValue();
    var gSubmitDateYYYY = gSubmitDate.substr(0, 4);
    var j = 1;
    var gAutoValue;
    if (gSubmitDate != "" && dts_List.getCellData(1, "SPECL_APPL_TP_CD") == "" && dts_List.getCellData(2, "SPECL_APPL_TP_CD") == "") {
        for (var i = 1; i <= 7; i++) {
            gAutoValue = dts_List.getCellData(i, "SPECL_APPL_YY");
            if (gAutoValue < gSubmitDateYYYY) {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '9';*/
                X = '9';
            } else if (gAutoValue >= gSubmitDateYYYY && j <= 5) {
                //5개년도 면제로 적용

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '1';*/
                X = '1';
                j++;
            } else {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                // 
                // ********************************************************************

                /*ORG SRC: dts_List.nameValue(i, "SPECL_APPL_TP_CD") = '2';*/
                X = '2';
            }
        }
    }
};





//FileSizeLimit 30MB		
scwin.canUploadFile = function() {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    var mySize = inf_find.FileInfo('size');
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    if (dts_fileList.getTotalRow() == 10) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
    if (!scwin.canUploadFile()) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
        return;
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = trs_Save.ErrorMsg;
    if (msg == "T") {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "특례기업관리 " + scwin.jobType));
        $c.frame.path("../").fn_Search();
        await $c.frame.CloseFrame();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "특례기업관리 " + scwin.jobType));
    }
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "특례기업관리 " + scwin.jobType);
};
scwin.trs_Delete_OnSuccess = async function() {
    var msg = trs_Delete.ErrorMsg;
    if (msg == "T") {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "특례기업관리 " + scwin.jobType));
        $c.frame.path("../").fn_Search();
        await $c.frame.CloseFrame();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "특례기업관리 " + scwin.jobType));
    }
};
scwin.trs_Delete_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "특례기업관리 " + scwin.jobType);
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_submitCal_onclick = function() {
    popUpCalendar2(edt_SubmitDate);
};
scwin.img_speclCal_onclick = function() {
    popUpCalendar2(edt_speclDate);
};
scwin.img_skilCal_onclick = function() {
    popUpCalendar2(edt_skilDate);
};
scwin.img_lineadd_onclick = function() {
    dts_List.insertRow();
};
scwin.img_linedel_onclick = function() {
    $c.cp.removeRow(dts_List, dts_List.getRowPosition());
};
scwin.grd_Grid_onclick = function() {
    //적용년도 클릭시 신청서 제출일 년도 포함 + 5년 은 면제로 자동선택 되도록 함

    //fn_autoYYYY();  

};
scwin.grd_Grid_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    // row를 생성해줌
    var k = 1;
    if (scwin.contnId == "I") {
        for (var i = dts_List.getTotalRow(); i < 10; i++) {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            dts_List.insertRow(); /*ORG SRC: dts_List.nameValue(k, "SPECL_APPL_YY") = gSTRT_YYYY + i;*/ X = scwin.gSTRT_YYYY + i;
            k++;
        }
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    $c.stf.showObj(file_name, false);
    $c.stf.showObj(txb_seq, false);
    scwin.contnId = $c.frame.path("../").scwin.contnId;
    //alert(contnId);
    if (scwin.contnId == null || scwin.contnId == "undefined" || scwin.contnId.length <= 0) {
        scwin.contnId = "I";
    }
    scwin.fn_setCode();
    if (scwin.contnId != "I") {
        scwin.sIsurCd = $c.frame.path("../").gIsurCd;
        scwin.sSeq = $c.frame.path("../").gSeq;
        scwin.sComNm = $c.frame.path("../").gComNm;
        txb_isur_cd.setValue(scwin.sIsurCd);
        txb_isur_cd.setDisabled('true');
        txb_com_abbrv.setValue(scwin.sComNm);
        txb_seq.setValue(scwin.sSeq);
        $c.stf.showObj(img_com_srch, false);

        //상세데이터
        scwin.fn_read(scwin.sIsurCd, scwin.sSeq);
    } else {
        $c.stf.showObj(btn_delete, false);

        //신규화면
        scwin.fn_setFileDataHeader();
        scwin.fn_SetHeader();
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.top = "35px";
    Grd_com_isur.style.left = "116px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
